  if (increment_pipe) {
    ++clc_pipe_consumer_state;
  }

  // Accumulator stage slice
  int acc_stage = [&] () {
    if constexpr (IsOverlappingAccum) {
      return accumulator_pipe_producer_state.phase() ^ 1;
    }
    else {
      return accumulator_pipe_producer_state.index();
    }
  }();

